node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update quantity of CI-0006 from 3 to 2
db.prepare(\"UPDATE cart_items SET quantity = 2 WHERE cart_item_id = 'CI-0006'\").run();

// Recalculate subtotal: CI-0005 (1×49) + CI-0006 (2×89) + CI-0007 (2×72) = 49 + 178 + 144 = 371
const newSubtotal = (1 * 49) + (2 * 89) + (2 * 72);
console.log('New subtotal:', newSubtotal);

// Get current cart to preserve other fields
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
const newTotal = newSubtotal - cart.discount_amount + cart.gift_wrap_fee - cart.loyalty_discount + cart.shipping_cost;
console.log('New total:', newTotal);

// Update cart subtotal and total
db.prepare(\"UPDATE carts SET subtotal = ?, total = ? WHERE cart_id = 'CART-user_58b0a2d6'\").run(newSubtotal, newTotal);

// Verify
const updated = db.prepare(\"SELECT * FROM cart_items WHERE cart_item_id = 'CI-0006'\").get();
const updatedCart = db.prepare(\"SELECT subtotal, total FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
console.log('\nUpdated CI-0006:', JSON.stringify(updated, null, 2));
console.log('Updated cart totals:', JSON.stringify(updatedCart, null, 2));
"

